  1: import promptAction from '@ohos.promptAction';
  2: import { DesignTokens } from '../../model/DesignTokens';
  3: import { ColorsInterface } from '../../model/TokenInterfaces';
  4: import { ThemeManager } from '../../manager/ThemeManager';
  5: import { WebDavSyncManager, WebDavSettings, WebDavSyncResult } from '../../sync/WebDavSyncManager';
  6: import { DataSyncManager } from '../../sync/DataSyncManager';
  7: import { WebDavStateStore } from '../../utils/WebDavStateStore';
  8: import { SelectOption } from './SettingsCommon';
  9: 
 10: interface DialogIndexResult {
 11:   index: number;
 12: }
 13: 
 14: const WEBDAV_AUTOSYNC_INTERVAL_HOURS: number[] = [1, 3, 6, 12, 24];
 15: const WEBDAV_AUTOSYNC_INTERVAL_OPTIONS: SelectOption[] = [
 16:   { value: '每1小时' },
 17:   { value: '每3小时' },
 18:   { value: '每6小时（默认）' },
 19:   { value: '每12小时' },
 20:   { value: '每24小时' }
 21: ];
 22: 
 23: @Component
 24: export struct SettingsSyncSection {
 25:   @Link webdavEndpoint: string;
 26:   @Link webdavUsername: string;
 27:   @Link webdavPassword: string;
 28:   @Link webdavSyncPassword: string;
 29:   @Link webdavRemoteRoot: string;
 30:   @Link showWebdavPassword: boolean;
 31:   @Link showWebdavSyncPassword: boolean;
 32:   @Link webdavAutoSyncEnabled: boolean;
 33:   @Link webdavAutoSyncIntervalIndex: number;
 34:   @Link webdavAutoSyncUploadModelEnabled: boolean;
 35:   @Link webdavAutoSyncUploadBackupEnabled: boolean;
 36:   @Link webdavAutoSyncLastSuccessMs: number;
 37:   @Link webdavAutoSyncLastError: string;
 38:   @StorageProp('ThemeRefreshToken') @Watch('onThemeChange') themeRefreshToken: number = 0;
 39:   @State private colors: ColorsInterface = ThemeManager.getInstance().getColors();
 40: 
 41:   @State webdavResult: string = '';
 42:   @State webdavBackupResult: string = '';
 43:   @State webdavBusy: boolean = false;
 44: 
 45:   private webdavManager: WebDavSyncManager = WebDavSyncManager.getInstance();
 46:   private webdavStateStore: WebDavStateStore = WebDavStateStore.getInstance();
 47:   private syncManager: DataSyncManager = DataSyncManager.getInstance();
 48: 
 49:   private onThemeChange(): void {
 50:     this.colors = ThemeManager.getInstance().getColors();
 51:   }
 52: 
 53:   aboutToAppear(): void {
 54:     void this.loadAutoSyncSettings();
 55:   }
 56: 
 57:   private async loadAutoSyncSettings(): Promise<void> {
 58:     try {
 59:       const enabled = await this.webdavStateStore.getAutoSyncEnabled();
 60:       const hours = await this.webdavStateStore.getAutoSyncIntervalHours();
 61:       const uploadModel = await this.webdavStateStore.getAutoSyncUploadModelEnabled();
 62:       const uploadBackup = await this.webdavStateStore.getAutoSyncUploadBackupEnabled();
 63:       const lastSuccess = await this.webdavStateStore.getAutoSyncLastSuccessMs();
 64:       const lastError = await this.webdavStateStore.getAutoSyncLastError();
 65: 
 66:       this.webdavAutoSyncEnabled = enabled;
 67:       this.webdavAutoSyncUploadModelEnabled = uploadModel;
 68:       this.webdavAutoSyncUploadBackupEnabled = uploadBackup;
 69:       this.webdavAutoSyncLastSuccessMs = lastSuccess;
 70:       this.webdavAutoSyncLastError = lastError;
 71: 
 72:       const index = WEBDAV_AUTOSYNC_INTERVAL_HOURS.indexOf(hours);
 73:       this.webdavAutoSyncIntervalIndex = index >= 0 ? index : 2;
 74:     } catch (e) {
 75:       console.error('[SettingsSyncSection] Failed to load auto sync settings:', e);
 76:     }
 77:   }
 78: 
 79:   private async saveWebDavAutoSyncSettings(): Promise<void> {
 80:     await this.webdavStateStore.setAutoSyncEnabled(this.webdavAutoSyncEnabled);
 81:     const hours = WEBDAV_AUTOSYNC_INTERVAL_HOURS[this.webdavAutoSyncIntervalIndex] ?? 6;
 82:     await this.webdavStateStore.setAutoSyncIntervalHours(hours);
 83:     await this.webdavStateStore.setAutoSyncUploadModelEnabled(this.webdavAutoSyncUploadModelEnabled);
 84:     await this.webdavStateStore.setAutoSyncUploadBackupEnabled(this.webdavAutoSyncUploadBackupEnabled);
 85:   }
 86: 
 87:   private formatWebDavAutoSyncLastSuccess(): string {
 88:     const ms = this.webdavAutoSyncLastSuccessMs;
 89:     if (ms <= 0) {
 90:       return '从未';
 91:     }
 92:     try {
 93:       return new Date(ms).toLocaleString();
 94:     } catch {
 95:       return String(ms);
 96:     }
 97:   }
 98: 
 99:   private async saveWebDavSettings(): Promise<boolean> {
100:     const s = new WebDavSettings(
101:       this.webdavEndpoint.trim(),
102:       this.webdavUsername.trim(),
103:       this.webdavPassword,
104:       this.webdavSyncPassword,
105:       this.webdavRemoteRoot.trim().length > 0 ? this.webdavRemoteRoot.trim() : '/weiyu_sync',
106:       true
107:     );
108:     const saved = await this.webdavManager.setSettings(s);
109:     this.webdavResult = saved ? '✅ WebDAV 设置已保存' : '⚠️ WebDAV 设置保存失败';
110:     return saved;
111:   }
112: 
113:   private readonly OPERATION_TIMEOUT = 120000; // 120秒超时
114: 
115:   private async runWithTimeout<T>(operation: () => Promise<T>, timeoutMs: number): Promise<T> {
116:     return Promise.race([
117:       operation(),
118:       new Promise<T>((_, reject) => {
119:         setTimeout(() => reject(new Error('操作超时，请检查网络连接')), timeoutMs);
120:       })
121:     ]);
122:   }
123: 
124:   private async runWebDavAction(fn: () => Promise<WebDavSyncResult>): Promise<void> {
125:     if (this.webdavBusy) return;
126:     this.webdavBusy = true;
127:     try {
128:       const res = await this.runWithTimeout(fn, this.OPERATION_TIMEOUT);
129:       this.webdavResult = res.success ? `✅ ${res.message}` : `⚠️ ${res.message}：${res.detail}`;
130:       promptAction.showToast({ message: res.message, duration: 1200 });
131:     } catch (e) {
132:       const msg = e instanceof Error ? e.message : String(e);
133:       this.webdavResult = `⚠️ WebDAV 操作异常：${msg}`;
134:       promptAction.showToast({ message: 'WebDAV 操作异常', duration: 1200 });
135:     } finally {
136:       this.webdavBusy = false;
137:     }
138:   }
139: 
140:   private async runWebDavBackupAction(fn: () => Promise<WebDavSyncResult>): Promise<void> {
141:     if (this.webdavBusy) return;
142:     this.webdavBusy = true;
143:     this.webdavBackupResult = '正在处理...';
144: 
145:     await new Promise<void>((resolve) => setTimeout(resolve, 50));
