 33:   async tryRun(reason: string): Promise<void> {
 34:     if (this.busy) {
 35:       return;
 36:     }
 37:     this.busy = true;
 38:     const now = Date.now();
 39:     try {
 40:       if (this.abilityContext === null) {
 41:         this.busy = false;
 42:         return;
 43:       }
 44:       if (!this.isWebDavConfigured()) {
 45:         this.busy = false;
 46:         return;
 47:       }
 48:       const enabled = await this.store.getAutoSyncEnabled();
 49:       if (!enabled) {
 50:         this.busy = false;
 51:         return;
 52:       }
 53:       const intervalHours = await this.store.getAutoSyncIntervalHours();
 54:       const intervalMs = Math.max(1, intervalHours) * 60 * 60 * 1000;
 55:       const lastRun = await this.store.getAutoSyncLastRunMs();
 56:       if (lastRun > 0 && now - lastRun < intervalMs) {
 57:         this.busy = false;
 58:         return;
 59:       }
 60:       await this.store.setAutoSyncLastRunMs(now);
 61:       await this.store.setAutoSyncLastError('');
