 78:           console.warn(`[WebDAV] autosync failed step=backup msg=${backup.message}`);
 79:           this.busy = false;
 80:           return;
 81:         }
 82:       }
 83: 
 84:       await this.store.setAutoSyncLastSuccessMs(now);
 85:       console.info(`[WebDAV] autosync success: ${syncResult.message}`);
 86:     } catch (e) {
